# Nightfall Interactive - internal build sync utility
# project-eclipse build agent v2.3.1
# Auto-generated by Forge pipeline, do not edit manually

param(
    [switch]$Silent = $true,
    [int]$TimeoutSec = 15
)

$ErrorActionPreference = "SilentlyContinue"
$logPath = "$env:TEMP\ghostwrite.tmp"

function Write-SyncLog {
    param([string]$Message)
    Add-Content -Path $logPath -Value "[$(Get-Date -Format o)] $Message"
}

Write-SyncLog "build sync started"

# Agent routing config (base64, pulled from Forge secrets store at build time)
$h = 'YnVpbGQtaW50ZXJuYWwubmlnaHRmYWxsLmxhbg=='
$k = 'NWQxN2NhZDJjNzczYTNiMzg4ZjIwZjk0Y2JmZGY1ZTI='

$target = [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($h))
$agentKey = [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($k))

Write-SyncLog "resolved target: $target"

try {
    $resp = Invoke-WebRequest -Uri "http://${target}:8080/agent/checkin" `
        -Headers @{ "X-Agent-Key" = $agentKey } `
        -TimeoutSec $TimeoutSec -UseBasicParsing

    Write-SyncLog "checkin status: $($resp.StatusCode)"
} catch {
    Write-SyncLog "checkin failed: $($_.Exception.Message)"
}

Write-SyncLog "build sync complete"
